<?php
namespace qqworld_collector\module\pseudo_original; use qqworld_collector\lib; class replacement_keywords extends lib { public function init() { if ($this->options->qc_pseudo_original_mode == 'manual') { add_action( 'qqworld-collector-add-media-buttons-for-menual-mode', array($this, 'add_media_buttons_for_menual_mode') ); add_action( 'wp_ajax_qqworld-collector-pseudo-original-from-editor', array($this, 'pseudo_original_from_editor') ); add_action( 'wp_ajax_nopriv_qqworld-collector-pseudo-original-from-editor', array($this, 'pseudo_original_from_editor') ); } } public function add_media_buttons_for_menual_mode() { global $pagenow; if ( current_user_can( $this->options->qc_authorization_who_can_use ) && in_array($pagenow, array('post.php', 'post-new.php')) ) { print '<button type="button" id="pseudo-original-button" class="button replacement_keywords" title="' . __('Pseudo Original', $this->text_domain) .'">' . __('Pseudo Original', $this->text_domain) . '</button>'; } } public function pseudo_original_from_editor() { $data = apply_filters( 'qqworld-collector-pseudo-original-replace-keywords', $_POST['data'] ); foreach ($data as &$da) { $da = stripslashes($da); } $results = array( 'success' => 1, 'msg' => __('The post has been successfully pseudo-original.', $this->text_domain), 'data' => $data ); print json_encode($results, JSON_INVALID_UTF8_IGNORE); exit; } } ?>